
/*
 * Program: EECS 348 Assignment 4 - Sudoku Solver
 * Description: Solves Sudoku puzzles using recursion and backtracking.
 * Inputs: Sudoku Puzzle that needs solving, provided in a text file with 81 characters (digits 1-9 and underscores for blanks).
 * Output: Original puzzles, all solutions, or "No solution found."
 * Collaborators: None.
 * Other sources: None.
 * Author: Dalton Brockert
 * Creation date: October 15, 2026.
 * Code origin: Generated by ChatGPT and to be reviewed and improved.
 */

#include <iostream> // Provides console input and output.
#include <fstream> // Allows the program to read files.
#include <string> // Provides the string data type.
#include <vector> // Provides a resizable list of characters.

using namespace std; // Avoids writing std:: before standard names.

class SudokuSolver { // Defines an object that solves Sudoku puzzles.
private: // Keeps these members accessible only inside the class.
    int grid[9][9]; // Stores the 9x9 Sudoku grid.
    string fileName; // Stores the current puzzle filename.
    int solutionCount; // Counts the solutions found.

    bool findEmptyCell(int &row, int &col) { // Finds the next blank cell.
        for (int r = 0; r < 9; r++) { // Checks each row.
            for (int c = 0; c < 9; c++) { // Checks each column.
                if (grid[r][c] == 0) { // Checks whether the cell is blank.
                    row = r; // Saves the blank cell's row.
                    col = c; // Saves the blank cell's column.
                    return true; // Reports that a blank was found.
                } // Ends the blank-cell check.
            } // Ends the column loop.
        } // Ends the row loop.
        return false; // Reports that no blank cells remain.
    } // Ends findEmptyCell.

    bool isSafe(int row, int col, int digit) { // Checks if a digit can fit.
        for (int c = 0; c < 9; c++) { // Checks every cell in the row.
            if (grid[row][c] == digit) { // Looks for the same digit.
                return false; // Rejects a duplicate in the row.
            } // Ends the row check.
        } // Ends the row loop.

        for (int r = 0; r < 9; r++) { // Checks every cell in the column.
            if (grid[r][col] == digit) { // Looks for the same digit.
                return false; // Rejects a duplicate in the column.
            } // Ends the column check.
        } // Ends the column loop.

        int blockRow = (row / 3) * 3; // Finds the block's first row.
        int blockCol = (col / 3) * 3; // Finds the block's first column.

        for (int r = blockRow; r < blockRow + 3; r++) { // Checks block rows.
            for (int c = blockCol; c < blockCol + 3; c++) { // Checks block columns.
                if (grid[r][c] == digit) { // Looks for the same digit.
                    return false; // Rejects a duplicate in the block.
                } // Ends the block check.
            } // Ends the inner loop.
        } // Ends the outer loop.

        return true; // Allows the digit if no conflict exists.
    } // Ends isSafe.

    bool initialGridIsValid() { // Checks the original puzzle for conflicts.
        for (int row = 0; row < 9; row++) { // Visits every row.
            for (int col = 0; col < 9; col++) { // Visits every column.
                int digit = grid[row][col]; // Saves the current cell value.

                if (digit == 0) { // Checks whether the cell is empty.
                    continue; // Skips empty cells.
                } // Ends the empty-cell check.

                grid[row][col] = 0; // Temporarily clears the current cell.
                bool valid = isSafe(row, col, digit); // Checks for conflicts.
                grid[row][col] = digit; // Restores the original digit.

                if (!valid) { // Checks whether a conflict was found.
                    return false; // Rejects the invalid puzzle.
                } // Ends the conflict check.
            } // Ends the column loop.
        } // Ends the row loop.

        return true; // Accepts the puzzle's starting digits.
    } // Ends initialGridIsValid.

    void printGrid() { // Prints the Sudoku grid.
        for (int row = 0; row < 9; row++) { // Prints each row.
            if (row % 3 == 0 && row != 0) { // Checks for a block boundary.
                cout << "------+-------+------" << endl; // Prints a divider.
            } // Ends the divider check.

            for (int col = 0; col < 9; col++) { // Prints each cell.
                if (col % 3 == 0 && col != 0) { // Checks for a block boundary.
                    cout << "| "; // Separates the vertical blocks.
                } // Ends the block-boundary check.

                if (grid[row][col] == 0) { // Checks for an empty cell.
                    cout << "_ "; // Prints an underscore for a blank.
                } else { // Handles cells containing digits.
                    cout << grid[row][col] << " "; // Prints the digit.
                } // Ends the cell-value check.
            } // Ends the column loop.

            cout << endl; // Moves to the next output line.
        } // Ends the row loop.
    } // Ends printGrid.

    void solveRecursive() { // Searches for every possible solution.
        int row; // Stores the next blank cell's row.
        int col; // Stores the next blank cell's column.

        if (!findEmptyCell(row, col)) { // Checks whether the grid is complete.
            solutionCount++; // Counts the completed solution.
            cout << "\nSolution " << solutionCount << ":" << endl; // Prints its number.
            printGrid(); // Prints the completed Sudoku grid.
            return; // Returns to search for other solutions.
        } // Ends the completed-grid check.

        for (int digit = 1; digit <= 9; digit++) { // Tries digits 1 through 9.
            if (isSafe(row, col, digit)) { // Checks whether the digit fits.
                grid[row][col] = digit; // Places the temporary digit.
                solveRecursive(); // Recursively solves the remaining cells.
                grid[row][col] = 0; // Removes the digit to backtrack.
            } // Ends the valid-digit check.
        } // Ends the digit loop.
    } // Ends solveRecursive.

public: // Makes these members accessible outside the class.
    SudokuSolver() { // Creates and initializes a solver object.
        solutionCount = 0; // Starts the solution count at zero.

        for (int row = 0; row < 9; row++) { // Visits every row.
            for (int col = 0; col < 9; col++) { // Visits every column.
                grid[row][col] = 0; // Marks every cell as empty.
            } // Ends the column loop.
        } // Ends the row loop.
    } // Ends the constructor.

    bool loadFromFile(const string &name) { // Reads a puzzle from a file.
        fileName = name; // Saves the filename.
        ifstream inputFile(fileName); // Opens the puzzle file.

        if (!inputFile.is_open()) { // Checks whether the file opened.
            cerr << "Error: Could not open " << fileName << endl; // Prints an error.
            return false; // Reports that loading failed.
        } // Ends the file-opening check.

        vector<char> cells; // Stores the puzzle's cell characters.
        char character; // Stores each character read from the file.

        while (inputFile.get(character)) { // Reads one character at a time.
            if ((character >= '1' && character <= '9') || character == '_') { // Checks for a cell.
                cells.push_back(character); // Saves the cell character.
            } else if (character != ' ' && character != '\t' && character != '\n' && character != '\r') { // Checks for invalid characters.
                cerr << "Error: Invalid character in " << fileName << endl; // Prints an error.
                inputFile.close(); // Closes the input file.
                return false; // Reports that loading failed.
            } // Ends the character check.
        } // Ends the file-reading loop.

        inputFile.close(); // Closes the file after reading.

        if (cells.size() != 81) { // Checks for exactly 81 cells.
            cerr << "Error: " << fileName << " must contain exactly 81 cells; found " << cells.size() << "." << endl; // Explains the size error.
            return false; // Rejects the incorrectly sized puzzle.
        } // Ends the cell-count check.

        int index = 0; // Tracks the next character to copy.
        for (int row = 0; row < 9; row++) { // Fills each row.
            for (int col = 0; col < 9; col++) { // Fills each column.
                if (cells[index] == '_') { // Checks for a blank character.
                    grid[row][col] = 0; // Stores blanks as zero.
                } else { // Handles digit characters.
                    grid[row][col] = cells[index] - '0'; // Converts the character to an integer.
                } // Ends the cell conversion.

                index++; // Moves to the next character.
            } // Ends the column loop.
        } // Ends the row loop.

        return true; // Reports that loading succeeded.
    } // Ends loadFromFile.

    void solve() { // Prints and solves the current puzzle.
        cout << "\n========================================" << endl; // Prints a top divider.
        cout << "Puzzle file: " << fileName << endl; // Prints the filename.
        cout << "========================================" << endl; // Prints a bottom divider.

        cout << "\nOriginal puzzle:" << endl; // Labels the original grid.
        printGrid(); // Displays the unsolved puzzle.

        if (!initialGridIsValid()) { // Checks for conflicting starting digits.
            cout << "\nPuzzle has conflicting starting digits." << endl; // Reports an invalid puzzle.
            return; // Stops solving this puzzle.
        } // Ends the starting-grid check.

        solutionCount = 0; // Resets the solution count.
        solveRecursive(); // Searches for every solution.

        if (solutionCount == 0) { // Checks whether any solution was found.
            cout << "\nNo solution found" << endl; // Reports that no solution exists.
        } else { // Handles puzzles with solutions.
            cout << "\nTotal solutions found: " << solutionCount << endl; // Prints the total.
        } // Ends the solution-count check.
    } // Ends solve.
}; // Ends the SudokuSolver class.

int main() { // Starts the program.
    string puzzleFiles[] = { // Lists the five input files.
        "puzzle1.txt", // First Sudoku puzzle.
        "puzzle2.txt", // Second Sudoku puzzle.
        "puzzle3.txt", // Third Sudoku puzzle.
        "puzzle4.txt", // Fourth Sudoku puzzle.
        "puzzle5.txt" // Fifth Sudoku puzzle.
    }; // Ends the filename list.

    for (int i = 0; i < 5; i++) { // Processes all five puzzles.
        SudokuSolver solver; // Creates a solver for this puzzle.

        if (solver.loadFromFile(puzzleFiles[i])) { // Loads the current puzzle.
            solver.solve(); // Solves it if loading succeeded.
        } // Ends the loading check.
    } // Ends the puzzle loop.

    return 0; // Ends the program successfully.
} // Ends main.
